"use client"

import * as React from "react"
import { Direction, Slider as SliderPrimitive } from "radix-ui"
import { cn } from "@/lib/utils"
import { MinecraftSurface } from "./minecraft-surface"
import { MinecraftText } from "./minecraft-text"
import { minecraftSliderSprites as sprites } from "./minecraft-slider-sprites"
import "./minecraft-slider.css"

function Slider({ className, defaultValue, value, min = 0, max = 100, scale = 2,
  label, style, disabled, orientation = "horizontal", dir: direction, inverted = false,
  onValueChange, onFocusCapture, onBlurCapture, onKeyDown, onMouseEnter, onMouseLeave, ...props }:
  React.ComponentProps<typeof SliderPrimitive.Root> & { scale?: 1 | 2 | 3; label?: string }) {
  const [uncontrolled, setUncontrolled] = React.useState(defaultValue ?? [min, max])
  const dir = Direction.useDirection(direction)
  const values = value ?? uncontrolled
  const [editing, setEditing] = React.useState(false)
  const [focused, setFocused] = React.useState(false)
  const [hovered, setHovered] = React.useState(false)
  const highlightTrack = !disabled && focused && !editing
  const highlightHandle = !disabled && (hovered || (focused && editing))
  return <SliderPrimitive.Root
    data-slot="slider"
    className={cn("mc-slider", className)}
    min={min} max={max} value={values} disabled={disabled} orientation={orientation} dir={dir} inverted={inverted}
    style={{ "--mc-scale": scale, ...style } as React.CSSProperties}
    onValueChange={next => { setUncontrolled(next); onValueChange?.(next) }}
    onFocusCapture={event => { onFocusCapture?.(event); if (!event.defaultPrevented) { setFocused(true); setEditing(true) } }}
    onBlurCapture={event => { onBlurCapture?.(event); if (!event.currentTarget.contains(event.relatedTarget)) { setFocused(false); setEditing(false) } }}
    onKeyDown={event => { onKeyDown?.(event); if (!event.defaultPrevented && (event.key === "Enter" || event.key === " ")) { event.preventDefault(); setEditing(current => !current) } }}
    onMouseEnter={event => { onMouseEnter?.(event); if (!event.defaultPrevented) setHovered(true) }}
    onMouseLeave={event => { onMouseLeave?.(event); if (!event.defaultPrevented) setHovered(false) }}
    {...props}
  >
    <SliderPrimitive.Track data-slot="slider-track" className="mc-slider-track">
      <MinecraftSurface sprite={highlightTrack ? sprites.slider_highlighted : sprites.slider} />
      <SliderPrimitive.Range data-slot="slider-range" className="mc-slider-range" />
    </SliderPrimitive.Track>
    {values.map((current, index) => {
      const fraction = max === min ? 0 : Math.min(1, Math.max(0, (current - min) / (max - min)))
      const reverse = orientation === "horizontal" ? (dir === "rtl") !== inverted : !inverted
      return <span key={index} className="mc-slider-position" style={{ "--mc-thumb-fraction": reverse ? 1 - fraction : fraction } as React.CSSProperties}>
        <SliderPrimitive.Thumb data-slot="slider-thumb" className="mc-slider-thumb" aria-label={values.length === 1 ? props["aria-label"] : undefined} aria-labelledby={values.length === 1 ? props["aria-labelledby"] : undefined}>
          <span className="mc-slider-handle"><MinecraftSurface sprite={highlightHandle ? sprites.slider_handle_highlighted : sprites.slider_handle} /></span>
        </SliderPrimitive.Thumb>
      </span>
    })}
    {label != null && <MinecraftText className="mc-slider-label">{label}</MinecraftText>}
  </SliderPrimitive.Root>
}
export { Slider }

@layer theme, base, components, utilities;
@layer components {
  .mc-slider {
    --mc-pixel: calc(1px * var(--mc-scale, 2));
    --mc-ink: #fff;
    --mc-shadow: #3f3f3f;
    position: relative;
    display: block;
    width: calc(200 * var(--mc-pixel));
    height: calc(20 * var(--mc-pixel));
    min-width: calc(8 * var(--mc-pixel));
    touch-action: none;
    user-select: none;
  }
  .mc-slider[data-disabled] { --mc-ink: #a0a0a0; --mc-shadow: #282828; }
  .mc-slider-track, .mc-slider-position { position: absolute; inset: 0; }
  .mc-slider-position { pointer-events: none; }
  .mc-slider-range { display: none; }
  .mc-slider-position > span:first-child {
    left: calc(round(down, (100% - 8 * var(--mc-pixel)) * var(--mc-thumb-fraction), var(--mc-pixel)) + 4 * var(--mc-pixel)) !important;
    right: auto !important;
    transform: translateX(-50%) !important;
    top: 0;
  }
  .mc-slider-thumb { display: block; width: calc(8 * var(--mc-pixel)); height: calc(20 * var(--mc-pixel)); outline: none; pointer-events: auto; }
  .mc-slider-handle { display: block; position: absolute; inset: 0; }
  .mc-slider-label {
    position: absolute;
    pointer-events: none;
    left: round(down, 50%, var(--mc-pixel));
    top: calc(round(down, (100% - 9 * var(--mc-pixel)) / 2, var(--mc-pixel)) + var(--mc-pixel));
    transform: translateX(round(up, -50%, var(--mc-pixel)));
  }
  .mc-slider[data-orientation="vertical"] { width: calc(20 * var(--mc-pixel)); height: calc(200 * var(--mc-pixel)); }
  .mc-slider[data-orientation="vertical"] .mc-slider-position > span:first-child {
    left: 0 !important;
    top: calc(round(down, (100% - 8 * var(--mc-pixel)) * var(--mc-thumb-fraction), var(--mc-pixel)) + 4 * var(--mc-pixel)) !important;
    bottom: auto !important;
    transform: translateY(-50%) !important;
  }
  .mc-slider[data-orientation="vertical"] .mc-slider-thumb { width: calc(20 * var(--mc-pixel)); height: calc(8 * var(--mc-pixel)); }
  .mc-slider[data-orientation="vertical"] .mc-slider-handle { width: calc(8 * var(--mc-pixel)); height: calc(20 * var(--mc-pixel)); inset: auto; left: 50%; top: 50%; transform: translate(-50%, -50%) rotate(90deg); }
}

import * as React from "react"
import "./minecraft-surface.css"

type Sprite = { width: number; height: number; border: { left: number; top: number; right: number; bottom: number }; stretch: boolean; image: string; pieces: readonly string[] }

function MinecraftSurface({ sprite }: { sprite: Sprite }) {
  const widths = [sprite.border.left, sprite.width - sprite.border.left - sprite.border.right, sprite.border.right]
  const heights = [sprite.border.top, sprite.height - sprite.border.top - sprite.border.bottom, sprite.border.bottom]
  return <span aria-hidden="true" className="mc-surface" style={{
    gridTemplateColumns: `calc(${widths[0]} * var(--mc-pixel)) minmax(0, 1fr) calc(${widths[2]} * var(--mc-pixel))`,
    gridTemplateRows: `calc(${heights[0]} * var(--mc-pixel)) minmax(0, 1fr) calc(${heights[2]} * var(--mc-pixel))`,
  } as React.CSSProperties}>
    {sprite.pieces.map((piece, index) => <span key={index} style={{ backgroundImage: piece,
      backgroundSize: sprite.stretch && (index % 3 === 1 || Math.floor(index / 3) === 1) ? "100% 100%" : `calc(${widths[index % 3]} * var(--mc-pixel)) calc(${heights[Math.floor(index / 3)]} * var(--mc-pixel))`,
    }} />)}
  </span>
}
export { MinecraftSurface }

@layer theme, base, components, utilities;
@layer components {
  .mc-surface {
    position: absolute;
    inset: 0;
    display: grid;
    pointer-events: none;
    image-rendering: pixelated;
  }
  .mc-surface > span { background-repeat: repeat; }
}

import * as React from "react"
import { minecraftGlyphs } from "./minecraft-font"
import "./minecraft-text.css"

function MinecraftText({ children, className }: { children: React.ReactNode; className?: string }) {
  if ((typeof children !== "string" && typeof children !== "number") || !/^[\x20-\x7e]*$/.test(String(children))) return <span className={className}>{children}</span>
  const text = String(children)
  return <span className={`mc-bitmap ${className ?? ""}`}>
    <span className="mc-text-pixels" aria-hidden="true">{Array.from(text, (char, index) => {
      const [x, y, advance] = minecraftGlyphs[char.charCodeAt(0) - 32]
      return <span key={index} className="mc-glyph" style={{ "--mc-glyph-x": x, "--mc-glyph-y": y, "--mc-advance": advance, visibility: char === " " ? "hidden" : undefined } as React.CSSProperties} />
    })}</span>
    <span className="mc-text-accessible">{text}</span>
  </span>
}
export { MinecraftText }

@layer theme, base, components, utilities;
@import "./minecraft-text-assets.css";
@layer components {
  .mc-bitmap { display: inline-flex; image-rendering: pixelated; --mc-pixel: calc(1px * var(--mc-scale, 2)); }
  .mc-bitmap > .mc-text-pixels { display: inline-flex; filter: drop-shadow(var(--mc-pixel) var(--mc-pixel) 0 var(--mc-shadow, #3f3f3f)); }
  .mc-bitmap .mc-glyph {
    display: block;
    width: calc(var(--mc-advance) * var(--mc-pixel));
    height: calc(8 * var(--mc-pixel));
    flex-shrink: 0;
    background-color: var(--mc-ink, #fff);
    mask-image: var(--mc-ascii-atlas);
    mask-size: calc(var(--mc-atlas-size) * var(--mc-pixel)) calc(var(--mc-atlas-size) * var(--mc-pixel));
    mask-position: calc(-1 * var(--mc-glyph-x) * var(--mc-pixel)) calc(-1 * var(--mc-glyph-y) * var(--mc-pixel));
    mask-repeat: no-repeat;
  }
  .mc-bitmap > .mc-text-accessible { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; border: 0; }
}
